-- Rollback of the runtime-role grants. GENERATED by `python -m pipeline.db_grants --rollback`; do not edit by hand.
-- Revokes every direct grant held by role mavlit_app in database mavlit_enrichment_test. Does NOT drop the role, change its memberships,
-- touch PUBLIC or any other role, or delete data. Switching DATABASE_URL back to the owner role does not do this.
\set ON_ERROR_STOP on
BEGIN;

-- Guard: right database, run by the owner or a superuser, role exists.
DO $guard$
BEGIN
    IF current_database() <> 'mavlit_enrichment_test' THEN
        RAISE EXCEPTION 'this script is for database mavlit_enrichment_test, not %', current_database();
    END IF;
    IF NOT (pg_has_role(current_user, 'mavlit_user', 'USAGE') OR (SELECT rolsuper FROM pg_roles WHERE rolname = current_user)) THEN
        RAISE EXCEPTION 'run this script as mavlit_user (or a superuser), not %', current_user;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'mavlit_app') THEN
        RAISE EXCEPTION 'role mavlit_app does not exist';
    END IF;
END
$guard$;

REVOKE ALL ON ALL TABLES IN SCHEMA "public" FROM "mavlit_app";
REVOKE ALL ON ALL SEQUENCES IN SCHEMA "public" FROM "mavlit_app";
DO $stray$
DECLARE obj record; app oid;
BEGIN
    SELECT oid INTO app FROM pg_roles WHERE rolname = 'mavlit_app';
    FOR obj IN
        SELECT n.nspname AS sch, c.relname AS rel, c.relkind AS kind
        FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_(toast|temp)' AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S')
          AND NOT (n.nspname = 'public' AND ((c.relkind <> 'S' AND c.relname IN ('apify_usage', 'brand_contacts', 'brand_instagram_users', 'brand_match_profile', 'brands_niches', 'brands_raw', 'contact_reveals', 'content_creator_re', 'contract_reviews', 'creator_brand_llm_rankings', 'creator_brand_llm_v3_rankings', 'creator_instagram_posts', 'creator_llm_cost', 'creator_niches', 'creator_profiles', 'early_access_signups', 'facebook_branded_content_checks', 'initial_brand_score', 'instagram_creator_commenters', 'instagram_posts', 'instagram_users', 'llm_usage', 'login_failures', 'meta_ads', 'own_brand_jobs', 'pitches', 'prompts', 'rate_estimates', 'saved_brands', 'test_brands_with_instagram_posts', 'test_creator_brand_partnership_posts', 'test_niches', 'youtube_sponsorships')) OR c.oid IN (SELECT s.oid FROM pg_class s JOIN pg_depend d ON d.objid = s.oid AND d.classid = 'pg_class'::regclass AND d.refclassid = 'pg_class'::regclass AND d.deptype IN ('a', 'i') JOIN pg_class t ON t.oid = d.refobjid JOIN pg_namespace tn ON tn.oid = t.relnamespace WHERE s.relkind = 'S' AND tn.nspname = 'public' AND t.relname IN ('apify_usage', 'brand_contacts', 'brand_instagram_users', 'brand_match_profile', 'brands_niches', 'brands_raw', 'contact_reveals', 'content_creator_re', 'contract_reviews', 'creator_brand_llm_rankings', 'creator_brand_llm_v3_rankings', 'creator_instagram_posts', 'creator_niches', 'creator_profiles', 'early_access_signups', 'facebook_branded_content_checks', 'initial_brand_score', 'instagram_creator_commenters', 'instagram_posts', 'instagram_users', 'llm_usage', 'login_failures', 'meta_ads', 'own_brand_jobs', 'pitches', 'prompts', 'rate_estimates', 'saved_brands', 'test_brands_with_instagram_posts', 'test_creator_brand_partnership_posts', 'test_niches', 'youtube_sponsorships'))))
          AND (EXISTS (SELECT 1 FROM aclexplode(c.relacl) a WHERE a.grantee = app)
               OR EXISTS (SELECT 1 FROM pg_attribute at, aclexplode(at.attacl) a WHERE at.attrelid = c.oid AND a.grantee = app))
        ORDER BY 1, 2
    LOOP
        EXECUTE 'REVOKE ALL ON ' || CASE WHEN obj.kind = 'S' THEN 'SEQUENCE ' ELSE 'TABLE ' END || quote_ident(obj.sch) || '.' || quote_ident(obj.rel) || ' FROM ' || quote_ident('mavlit_app');
        RAISE NOTICE USING MESSAGE = 'revoked a direct grant outside the plan from ' || 'mavlit_app' || ' on ' || obj.sch || '.' || obj.rel;
    END LOOP;
    FOR obj IN
        SELECT n.nspname AS sch FROM pg_namespace n
        WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_(toast|temp)' AND n.nspname <> 'public' AND EXISTS (SELECT 1 FROM aclexplode(n.nspacl) a WHERE a.grantee = app)
        ORDER BY 1
    LOOP
        EXECUTE 'REVOKE ALL ON SCHEMA ' || quote_ident(obj.sch) || ' FROM ' || quote_ident('mavlit_app');
        RAISE NOTICE USING MESSAGE = 'revoked a direct schema grant outside the plan from ' || 'mavlit_app' || ' on ' || obj.sch;
    END LOOP;
END
$stray$;   -- any other schema / object outside the plan
REVOKE ALL ON SCHEMA "public" FROM "mavlit_app";
DO $rbdb$
BEGIN
    EXECUTE 'REVOKE ALL ON DATABASE ' || quote_ident(current_database()) || ' FROM ' || quote_ident('mavlit_app');
END
$rbdb$;

-- Verify: no direct grant to the role may remain anywhere in this database.
DO $verify$
DECLARE app oid; left_over text;
BEGIN
    SELECT oid INTO app FROM pg_roles WHERE rolname = 'mavlit_app';
    SELECT string_agg(x.what, ', ' ORDER BY x.what) INTO left_over FROM (
        SELECT 'relation ' || n.nspname || '.' || c.relname AS what FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE EXISTS (SELECT 1 FROM aclexplode(c.relacl) a WHERE a.grantee = app)
               OR EXISTS (SELECT 1 FROM pg_attribute at, aclexplode(at.attacl) a WHERE at.attrelid = c.oid AND a.grantee = app)
        UNION ALL SELECT 'schema ' || n.nspname FROM pg_namespace n WHERE EXISTS (SELECT 1 FROM aclexplode(n.nspacl) a WHERE a.grantee = app)
        UNION ALL SELECT 'database ' || d.datname FROM pg_database d WHERE d.datname = current_database() AND EXISTS (SELECT 1 FROM aclexplode(d.datacl) a WHERE a.grantee = app)
    ) x;
    IF left_over IS NOT NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'direct grants remain: ' || left_over;
    END IF;
END
$verify$;

COMMIT;

-- Not done here, on purpose: dropping the role (DROP OWNED BY / DROP ROLE), REVOKE of memberships (REVOKE <role> FROM <role>),
-- changes to PUBLIC, and anything touching data.
